package watch

import (
	"testing"
	"time"
)

// The engine tests run on synthetic times — a fixed base plus whole
// seconds, a fresh 5 s window per test — never sleeps (D3).
var (
	base     = time.Date(2026, 11, 11, 12, 0, 0, 0, time.UTC)
	debounce = 5 * time.Second
)

func at(seconds int) time.Time { return base.Add(time.Duration(seconds) * time.Second) }

func newTestEngine() *engine { return newEngine(debounce) }

func TestEngineDebounceQuietWindowFiresOnce(t *testing.T) {
	eng := newTestEngine()
	const lib = 1

	// A burst of writes, then quiet: the window arms at the LAST event.
	eng.observe(at(0), lib)
	eng.observe(at(2), lib)
	eng.observe(at(4), lib)

	if eng.dueFires(at(8), lib) {
		t.Fatal("fired before the last event's quiet window expired (4s + 5s = 9s)")
	}
	if !eng.dueFires(at(9), lib) {
		t.Fatal("did not fire exactly at the quiet-window deadline")
	}
	// Armed while running: the same expired window reports no second fire.
	if eng.dueFires(at(9), lib) || eng.dueFires(at(20), lib) {
		t.Fatal("fired more than once for one quiet window")
	}

	// A clean successful completion disarms: no fire until the next event.
	eng.completed(at(10), lib, true)
	if eng.dueFires(at(30), lib) {
		t.Fatal("refired after a clean completion with no new events")
	}
}

func TestEngineEventExtendsDeadline(t *testing.T) {
	eng := newTestEngine()
	const lib = 1

	eng.observe(at(0), lib) // window expires at 5s
	if eng.dueFires(at(4), lib) {
		t.Fatal("fired before the window expired")
	}

	// An event inside the window pushes the fire out to 4s + 5s = 9s —
	// a quiet window, not a fixed delay from the first event.
	eng.observe(at(4), lib)
	if eng.dueFires(at(5), lib) {
		t.Fatal("fired at the pre-extension deadline — the window did not extend")
	}
	if !eng.dueFires(at(9), lib) {
		t.Fatal("did not fire at the extended deadline")
	}
}

func TestEngineCompletedRefiresOnDirty(t *testing.T) {
	eng := newTestEngine()
	const lib = 1

	eng.observe(at(0), lib)
	if !eng.dueFires(at(5), lib) {
		t.Fatal("scan did not arm at the window expiry")
	}

	// An event observed mid-run only marks the library dirty.
	eng.observe(at(7), lib)
	if eng.dueFires(at(8), lib) {
		t.Fatal("fired while the scan was running")
	}

	// completed turns the dirty mark into one trailing scan, re-armed at
	// the completion time's quiet window (8s + 5s = 13s).
	eng.completed(at(8), lib, true)
	if eng.dueFires(at(12), lib) {
		t.Fatal("trailing scan fired before its quiet window")
	}
	if !eng.dueFires(at(13), lib) {
		t.Fatal("the dirty library did not get its one trailing fire")
	}
	// Exactly one trailing fire: armed until completed, then disarmed.
	if eng.dueFires(at(14), lib) {
		t.Fatal("more than one trailing fire")
	}
	eng.completed(at(14), lib, true)
	if eng.dueFires(at(40), lib) {
		t.Fatal("refired after the trailing scan completed cleanly")
	}
}

func TestEngineCompletedRefiresOnFailure(t *testing.T) {
	eng := newTestEngine()
	const lib = 1

	eng.observe(at(0), lib)
	if !eng.dueFires(at(5), lib) {
		t.Fatal("scan did not arm at the window expiry")
	}

	// A failed scan re-arms without any dirty mark: the retry window runs
	// from the completion time (6s + 5s = 11s).
	eng.completed(at(6), lib, false)
	if eng.dueFires(at(10), lib) {
		t.Fatal("retry fired before its quiet window")
	}
	if !eng.dueFires(at(11), lib) {
		t.Fatal("a failed scan did not re-arm a retry")
	}
	eng.completed(at(11), lib, true)
	if eng.dueFires(at(40), lib) {
		t.Fatal("refired after the retry completed cleanly")
	}
}

func TestEngineDistinctLibrariesIndependent(t *testing.T) {
	eng := newTestEngine()
	const libA, libB = 1, 2

	// Library A's scan is running.
	eng.observe(at(0), libA)
	if !eng.dueFires(at(5), libA) {
		t.Fatal("library A did not arm at its window expiry")
	}

	// Library B's window arms and fires while A is running: one library's
	// running scan never blocks another's fire.
	eng.observe(at(1), libB)
	if eng.dueFires(at(5), libB) {
		t.Fatal("library B fired before its own window expired")
	}
	if !eng.dueFires(at(6), libB) {
		t.Fatal("library B's fire was blocked by library A's running scan")
	}

	// B's state never touches A's: A stays armed, B's completion leaves
	// A armed until its own completed call.
	eng.completed(at(7), libB, true)
	if eng.dueFires(at(8), libB) {
		t.Fatal("library B refired after a clean completion")
	}
	eng.completed(at(8), libA, true)
	if eng.dueFires(at(9), libA) || eng.dueFires(at(9), libB) {
		t.Fatal("a library refired after its own clean completion")
	}
}
